#include <stdio.h>
int recursive(int n) {
int sum;
if (n > 2) {
sum = recursive(n-1) + recursive(n-2);
printf("%d ", sum);
}
else
sum = n;
return sum;
}
int main(void) {
int result;
result = recursive(5);
printf("%d", result);
return 0;
